package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
public final class CodeTemplateCorpusTests {
 static String read(Path path)throws Exception{return new String(Files.readAllBytes(path),StandardCharsets.UTF_8);}static String hash(String text)throws Exception{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte n:bytes)b.append(String.format(Locale.ROOT,"%02x",n&255));return b.toString();}
 static String mapping(FlowSourceText text)throws Exception{StringBuilder b=new StringBuilder();for(FlowSourceText.Line line:text.lines){b.append(line.number).append(',').append(line.start).append(',').append(line.length);for(FlowSourceText.Origin origin:line.origins)b.append('|').append(origin.functionId==null?"":origin.functionId).append(':').append(origin.nodeId);b.append('\n');}return hash(b.toString());}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),fixtures=root.resolve("../javascript-source-qa/fixtures"),assets=Paths.get(args[1]);List<Path> files=new ArrayList<>();try(DirectoryStream<Path> stream=Files.newDirectoryStream(fixtures,"*.frociart")){for(Path file:stream)files.add(file);}Collections.sort(files);List<String> reports=new ArrayList<>();int generated=0,rejected=0;
  for(Path file:files){String name=file.getFileName().toString().replace(".frociart","");FlowModel.Document document=FlowCodec.decode(read(file));FlowSource.Program program=FlowSource.compile(document);if(!program.canGenerate()){rejected++;continue;}String before=FlowCodec.encode(document);
   for(FlowSourceTarget target:FlowSourceTarget.ALL){FlowSourceText source=target.generate(program,read(assets.resolve(target.runtime)));String comment=target==FlowSourceTarget.PYTHON?"#":"//";FlowCodeTemplate template=FlowCodeTemplate.create("Personalizzato "+target.name,target.id,target.extension,"Esegui con il compilatore del linguaggio",comment+" Titolo: {{ project.title | literal }}\n{# Il codice resta completo e mappato #}{{ source }}");FlowSourceText result=template.generate(program,source);if(!result.text.endsWith(source.text)||!before.equals(FlowCodec.encode(document)))throw new AssertionError("Source or project modified: "+name);reports.add(name+"\t"+target.id+"\t"+hash(result.text)+"\t"+mapping(result));generated++;}
   FlowCodeTemplate raw=FlowCodeTemplate.create("Inventario","custom","txt","", "{{ program.title }}\n{% for scope in program.scopes %}{{ scope.key }} {{ scope.name }} {{ scope.returnType }} {{ scope.symbolNames | join:', ' }}\n{% for p in scope.parameters %}{{ p.identifier }} {{ p.type }} {{ p.array }} {{ p.reference }}\n{% endfor %}{% for b in scope.blocks %}{{ b.id }} {{ b.kind }} {{ b.text | literal }} {{ b.next }} {{ b.yes }} {{ b.no }} {{ b.fileReading }} {{ b.fileNewline }} {{ b.turtleDraw }} {{ b.turtleLeft }} {{ b.outputNewline }}\n{% endfor %}{% for n in scope.notes %}{{ n.text | literal }}\n{% endfor %}{% endfor %}");FlowSourceText result=raw.generate(program,null);reports.add(name+"\tcustom\t"+hash(result.text)+"\t"+mapping(result));generated++;
  }Files.write(root.resolve("android-corpus.tsv"),reports,StandardCharsets.UTF_8);List<String> expected=Files.readAllLines(root.resolve("pc-corpus.tsv"),StandardCharsets.UTF_8);for(int i=0;i<reports.size();i++)if(!reports.get(i).equals(expected.get(i)))throw new AssertionError("Corpus mismatch: "+reports.get(i)+" expected "+expected.get(i));if(reports.size()!=expected.size())throw new AssertionError("Corpus count mismatch");
  FlowSource.Program sample=FlowSource.compile(FlowCodec.decode(read(root.resolve("sample.frociart"))));List<String> outcomes=new ArrayList<>();for(String line:Files.readAllLines(root.resolve("pc-cases.tsv"),StandardCharsets.UTF_8)){String id=line.split("\t")[0];String actual;try{FlowSourceText result=FlowCodeTemplate.parse(read(root.resolve("cases").resolve(id+".frotemplate"))).generate(sample,null);actual=id+"\tPASS\t"+hash(result.text)+"\t"+mapping(result);}catch(IllegalArgumentException ex){actual=id+"\tREJECT";}if(!actual.equals(line))throw new AssertionError("Parser case mismatch: "+actual+" expected "+line);outcomes.add(actual);}Files.write(root.resolve("android-cases.tsv"),outcomes,StandardCharsets.UTF_8);
  System.out.println("TEMPLATE_CORPUS_ANDROID PASS generated="+generated+" invalid="+rejected+" parserCases="+outcomes.size());
 }
}
